# Таблица товаров и специальные действия с ней.
from final_project_sql_m26_555.dbtable import DbTable


class ProductsTable(DbTable):
    def table_name(self):
        return self.dbconn.prefix + "product"

    def columns(self):
        return {
            "id_product": ["integer", "GENERATED BY DEFAULT AS IDENTITY", "PRIMARY KEY"],
            "id_rack": ["integer", "NOT NULL", "REFERENCES rack(id_rack)"],
            "id_client": ["integer", "NOT NULL", "REFERENCES clients(id_client)"],
            "height": ["numeric", "NOT NULL", "CHECK (height > 0)"],
            "width": ["numeric", "NOT NULL", "CHECK (width > 0)"],
            "lengths": ["numeric", "NOT NULL", "CHECK (lengths > 0)"],
            "weight": ["numeric", "NOT NULL", "CHECK (weight > 0)"],
            "date_of_receipt": ["date", "NOT NULL", "DEFAULT CURRENT_DATE"],
            "contract_number": ["varchar(50)", "NOT NULL"],
            "end_date": ["date"],
            "min_temperature": ["numeric"],
            "max_temperature": ["numeric"],
            "min_humidity": ["numeric"],
            "max_humidity": ["numeric"],
            "positions": ["integer", "NOT NULL", "CHECK (positions > 0)"],
        }

    def primary_key(self):
        return ["id_product"]

    def column_names_without_id(self):
        return [
            "id_rack", "id_client", "height", "width", "lengths", "weight",
            "date_of_receipt", "contract_number", "end_date",
            "min_temperature", "max_temperature", "min_humidity",
            "max_humidity", "positions"
        ]

    def all_by_client_id(self, client_id):
        sql = f"""
            SELECT p.id_product, p.id_rack, r.rack_number, pr.name,
                   p.height, p.width, p.lengths, p.weight, p.date_of_receipt,
                   p.contract_number, p.end_date, p.min_temperature,
                   p.max_temperature, p.min_humidity, p.max_humidity, p.positions
            FROM {self.table_name()} p
            JOIN {self.dbconn.prefix}rack r ON r.id_rack = p.id_rack
            JOIN {self.dbconn.prefix}premises pr ON pr.id_premise = r.id_premise
            WHERE p.id_client = %s
            ORDER BY p.id_product
        """
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (client_id,))
            return cur.fetchall()

    def position_exists(self, rack_id, position):
        sql = f"""
            SELECT EXISTS (
                SELECT 1
                FROM {self.table_name()}
                WHERE id_rack = %s AND positions = %s
            )
        """
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (rack_id, position))
            return cur.fetchone()[0]

    def add_product(self, values):
        self.insert_one(values)

    def delete(self, product_id, client_id):
        sql = f"DELETE FROM {self.table_name()} WHERE id_product = %s AND id_client = %s"
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql, (product_id, client_id))
            changed = cur.rowcount
        self.dbconn.conn.commit()
        return changed

    def racks(self):
        sql = f"""
            SELECT r.id_rack, r.rack_number, pr.name, r.number_of_places
            FROM {self.dbconn.prefix}rack r
            JOIN {self.dbconn.prefix}premises pr ON pr.id_premise = r.id_premise
            ORDER BY pr.name, r.rack_number
        """
        with self.dbconn.conn.cursor() as cur:
            cur.execute(sql)
            return cur.fetchall()
